  identity={"pskg:documentName": "Employment information"}
- ref=b1__temp_doc_account_statements
  class=pskg:RequiredDocument
  identity={"pskg:documentName": "Account statements"}
- ref=b1__temp_doc_financial_capacity_proof
  class=pskg:RequiredDocument
  identity={"pskg:documentName": "Documents proving changes in financial capacity"}
- ref=b2__temp_rule_app_conditions
  class=pskg:BusinessRule
  identity={"pskg:businessRuleCondition": "Individual customers may submit an application when they meet the basic conditions:\n\n- At least 20 years old at the time of application.\n- Not older than 60 years at the time of application under normal policy.\n- Have valid identification documents.\n- Have verifiable residence information.\n- Have lawful employment or a lawful source of income.\n- Be able to provide proof of income.\n- Normally have net income of at least **10 million VND/month**.\n- Have an appropriate credit history.\n- Not fall under cases restricted from receiving credit under applicable regulations."}
- ref=b2__temp_rule_salaried_favorable
  class=pskg:BusinessRule
  identity={"pskg:businessRuleCondition": "For salaried customers, working at the current employer for **at least 03 months** and having a total continuous employment period of at least 12 months may be viewed more favorably."}
- ref=b2__temp_rule_approval_discretion
  class=pskg:BusinessRule
  identity={"pskg:businessRuleCondition": "The fact that a customer:\n\n- Earns more than 10 million VND.\n- Meets the age requirement.\n- Has an employment contract.\n- Has a salary account.\n\ndoes not mean the customer will definitely be issued a card.\n\nThe bank also assesses:\n\n- Existing financial obligations.\n- Credit quality.\n- Repayment ability.\n- Stability of income sources.\n- Actual application documents.\n- Other risk factors."}
- ref=b2__temp_rule_no_advance_commitment
  class=pskg:BusinessRule
  identity={"pskg:businessRuleCondition": "Employees must not commit in advance to a credit limit or approval result."}
- ref=b2__temp_rule_additional_appraisal
  class=pskg:BusinessRule
  identity={"pskg:businessRuleCondition": "Some cases may require deeper review:\n\n- Customers with multiple loans.\n- Customers with multiple credit cards at other institutions.\n- Existing card limits that are high relative to income.\n- Customers using a large portion of their existing credit limit.\n- History of late payments.\n- Income from multiple sources.\n- Highly variable income.\n- Self-employed customers.\n- Employment or residence information that is difficult to verify."}
- ref=b2__temp_doc_citizen_id

